// The lookup is emitted with the table on purpose. It is the exact
// inverse of the mapping build_cube_map() used to fill it in, and the
// two going out of step would not crash or warn -- it would quietly put
// Africa in the Pacific. Generating both together means they cannot.
//
// `d` must be a UNIT vector in the same Earth-centred axes as
// globe_data.h. Returns true if that direction is over land.
inline bool at(float dx, float dy, float dz) {
    const float ax = std::fabs(dx), ay = std::fabs(dy), az = std::fabs(dz);

    // Which cube face the direction points at: the dominant axis.
    int face;
    float m, sc, tc;
    if (ax >= ay && ax >= az) { m = ax; face = dx > 0.0f ? 0 : 1; sc = dy; tc = dz; }
    else if (ay >= az)        { m = ay; face = dy > 0.0f ? 2 : 3; sc = dx; tc = dz; }
    else                      { m = az; face = dz > 0.0f ? 4 : 5; sc = dx; tc = dy; }

    // One reciprocal and two multiplies, NOT two divisions: a float
    // divide on an ESP32 is a call to __divsf3, and this runs once per
    // pixel of the disc. `m` cannot be zero -- the largest component of a
    // unit vector is at least 0.577.
    const float inv = 1.0f / m;
    int i = static_cast<int>((sc * inv + 1.0f) * 0.5f * kFaceN);
    int j = static_cast<int>((tc * inv + 1.0f) * 0.5f * kFaceN);
    if (i < 0) i = 0; else if (i >= kFaceN) i = kFaceN - 1;
    if (j < 0) j = 0; else if (j >= kFaceN) j = kFaceN - 1;

    const int idx = (face * kFaceN + j) * kFaceN + i;
    return (kBits[idx >> 3] >> (idx & 7)) & 1u;
}

